        ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }),
          content: `<p>🏚️ <strong>${item.name}</strong> ${on ? "active" : "ended"} — ${on ? "spaces you move through become dangerous terrain (this scene)." : "no longer leaving terrain."}</p>` });
